// ✅ Composant pour afficher le modèle FSAE Pedal
function FSAEPedal({ position = [0, -10, 0], scale = [9, 9, 9] }) {
  const { scene } = useGLTF(fsaePedalModel);
  scene.position.set(1, -0.5, 0);
  scene.rotation.set(0, Math.PI, 0);
  return <primitive object={scene} scale={scale} />;
}
function CCDCooling({ scale = [20, 20, 20] }) {
  const { scene } = useGLTF(ccdCoolingModel);
  scene.position.set(1, 0, 0);
  scene.rotation.set(0, Math.PI, 0);
  return <primitive object={scene} scale={scale} />;
}

